import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Gestión de indexación","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Unidades locales","slug":"_1-unidades-locales","link":"#_1-unidades-locales","children":[]},{"level":2,"title":"2. Unidades de red","slug":"_2-unidades-de-red","link":"#_2-unidades-de-red","children":[]},{"level":2,"title":"3. WSL (Subsistema de Windows para Linux)","slug":"_3-wsl-subsistema-de-windows-para-linux","link":"#_3-wsl-subsistema-de-windows-para-linux","children":[]},{"level":2,"title":"4. Carpetas","slug":"_4-carpetas","link":"#_4-carpetas","children":[]},{"level":2,"title":"5. Reglas de exclusión","slug":"_5-reglas-de-exclusion","link":"#_5-reglas-de-exclusion","children":[]}],"relativePath":"es-ES/user-guide/settings/index-drives.md","filePath":"es-ES/user-guide/settings/index-drives.md","lastUpdated":1792595869000}`),a={name:`es-ES/user-guide/settings/index-drives.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="gestion-de-indexacion" tabindex="-1">Gestión de indexación <a class="header-anchor" href="#gestion-de-indexacion" aria-label="Permalink to “Gestión de indexación”">​</a></h1><p>La página de Indexación controla el alcance, la frecuencia de actualización y las reglas de exclusión para discos duros locales, recursos de red, distribuciones WSL y carpetas personalizadas. Contiene cinco pestañas: <strong>Unidades locales</strong>, <strong>Unidades de red</strong>, <strong>WSL</strong> (visible solo si se detectan distribuciones), <strong>Carpetas</strong> y <strong>Reglas de exclusión</strong>.</p><h2 id="_1-unidades-locales" tabindex="-1">1. Unidades locales <a class="header-anchor" href="#_1-unidades-locales" aria-label="Permalink to “1. Unidades locales”">​</a></h2><ul><li><strong>Tarjeta de estado superior</strong>: Muestra el total de unidades físicas y elementos indexados, con un botón global de <strong>Reconstruir índice</strong>.</li><li><strong>Filas de unidades</strong>: <ul><li><strong>Casilla de activación</strong>: Activa o desactiva la indexación para cada partición individual.</li><li><strong>Sistema de archivos y estado</strong>: Muestra el tipo de sistema de archivos (NTFS, ReFS, FAT32, exFAT), estado y recuento de elementos.</li><li><strong>Acciones por unidad</strong>: Botones independientes de <strong>Reconstruir</strong> y <strong>Eliminar</strong>; muestra un botón dinámico de <strong>Detener</strong> durante el escaneo.</li></ul></li><li><strong>Seguimiento en tiempo real</strong>: Los volúmenes NTFS / ReFS se sincronizan leyendo el diario de cambios USN de Windows; los volúmenes FAT32 / exFAT monitorizan eventos del sistema de archivos.</li><li><strong>Reconstrucción sin interrupciones</strong>: Durante la reconstrucción de una unidad, el índice existente sigue respondiendo a las consultas hasta que el nuevo termina y lo reemplaza de una sola vez. Si se interrumpe, se reanuda desde el último punto en el siguiente inicio.</li></ul><h2 id="_2-unidades-de-red" tabindex="-1">2. Unidades de red <a class="header-anchor" href="#_2-unidades-de-red" aria-label="Permalink to “2. Unidades de red”">​</a></h2><ul><li><strong>Soporte de almacenamiento en red</strong>: Lista todas las unidades de red asignadas en Windows (SMB / NAS).</li><li><strong>Modo de actualización</strong>: Al carecer de diarios USN locales, se puede programar su sondeo: <ul><li><strong>Manual</strong> — Se actualiza solo al pulsar &quot;Reconstruir índice&quot;.</li><li><strong>Cada 15 minutos</strong> — Recomendado para recursos colaborativos activos.</li><li><strong>Cada hora</strong> — Escaneo periódico equilibrado.</li><li><strong>Diario</strong> — Ideal para almacenamiento estático o de archivo.</li></ul></li><li><strong>Protección contra bucles de enlaces simbólicos</strong>: Algoritmos internos de detección de bucles evitan atascos provocados por enlaces simbólicos recursivos en carpetas NAS.</li></ul><h2 id="_3-wsl-subsistema-de-windows-para-linux" tabindex="-1">3. WSL (Subsistema de Windows para Linux) <a class="header-anchor" href="#_3-wsl-subsistema-de-windows-para-linux" aria-label="Permalink to “3. WSL (Subsistema de Windows para Linux)”">​</a></h2><p>Aparece automáticamente si se detecta al menos una distribución WSL instalada:</p><ul><li><strong>Detección automática</strong>: Reconoce Ubuntu, Debian, Arch y otras distribuciones.</li><li><strong>Estado y programación</strong>: Misma gestión y modos de actualización (Manual / 15 min / Cada hora / Diario).</li><li><strong>Consultas con latencia cero</strong>: Busca directamente en el índice en memoria sin despertar ni ralentizar el subsistema Linux.</li></ul><h2 id="_4-carpetas" tabindex="-1">4. Carpetas <a class="header-anchor" href="#_4-carpetas" aria-label="Permalink to “4. Carpetas”">​</a></h2><p>Útil cuando se desea indexar carpetas de trabajo específicas en lugar de volúmenes completos:</p><ul><li><strong>Adición múltiple</strong>: Pulsa <strong>Añadir carpeta</strong> para abrir un selector que permite selecciones múltiples con <code>Ctrl</code> o <code>Shift</code>.</li><li><strong>Rutas UNC</strong>: Admite rutas compartidas de red (p. ej. <code>\\\\server\\share\\projects</code>).</li><li><strong>Programación independiente</strong>: Cada carpeta dispone de su propio interruptor, contador y modo de actualización.</li></ul><h2 id="_5-reglas-de-exclusion" tabindex="-1">5. Reglas de exclusión <a class="header-anchor" href="#_5-reglas-de-exclusion" aria-label="Permalink to “5. Reglas de exclusión”">​</a></h2><p>Las reglas de exclusión filtran los resultados de búsqueda y limitan hasta dónde descienden los recorridos de red, WSL y carpetas. No detienen la indexación de un disco local: un volumen local siempre se recorre por completo, así que una ruta como <code>E:\\</code> en esta lista solo oculta sus resultados. Para detener la indexación de un disco local, desactívalo en <strong>Unidades locales</strong>. Las reglas forman <strong>una lista única</strong>, sin subpestañas. Cada regla combina una coincidencia y un nivel; la coincidencia se deduce de cómo se escribe el texto y el cuadro de entrada lo muestra como <strong>Detectado:</strong>.</p><ul><li><strong>Ruta completa</strong>: empieza con una letra de unidad (<code>D:\\Cache</code>), una ruta UNC (<code>\\\\server\\share</code>), una variable de entorno (<code>%ProgramData%</code>, <code>%APPDATA%</code>) o una ruta virtual <code>shell:</code>. Cubre esa carpeta y todo su contenido.</li><li><strong>Comodín</strong>: cualquier otra escritura. <code>*</code> coincide dentro de un mismo nivel (<code>*.log</code>), <code>?</code> con un carácter y <code>**</code> de forma recursiva (<code>**\\node_modules\\**</code>). Una regla sin separadores coincide por nombre a cualquier profundidad (<code>node_modules</code>, <code>*.tmp</code>); una regla con separadores se ancla desde la raíz de la unidad, de modo que <code>Listary\\abc</code> alcanza <code>C:\\Listary\\abc</code> y su contenido, pero no <code>D:\\work\\Listary\\abc</code>.</li><li><strong>Expresión regular</strong>: escribe entre barras, p. ej. <code>/^\\./</code> para archivos ocultos y <code>/~\\$/</code> para bloqueos temporales de Office. Se evalúa como coincidencia parcial sobre la ruta completa o el nombre de archivo. Usa un comodín siempre que puedas: una expresión regular se interpreta en cada coincidencia y cuesta más.</li></ul><p>El <strong>nivel</strong> decide qué ocurre: <strong>Excluir</strong> oculta el elemento y <strong>Baja</strong>, <strong>Normal</strong> y <strong>Alta</strong> solo cambian el orden; una regla alta puede fijarse al principio marcando la casilla. El nivel se elige en el desplegable de la derecha de la fila o se escribe como prefijo: <code>!</code> excluir, <code>-</code> bajo, <code>+</code> alto, sin prefijo normal. Una barra invertida inicial hace literal el prefijo.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>El prefijo solo se retira en el cuadro <strong>Añadir...</strong> y en <strong>Edición por lotes</strong>. Al editar una regla existente en su propia fila el texto se toma al pie de la letra, así que cambia el nivel con el desplegable: un <code>!</code> que queda dentro de un comodín se convierte en un carácter de la ruta y, como las rutas de Windows no llevan <code>!</code>, esa regla no puede coincidir con nada y la página no muestra ningún error.</p></div><p>En discos locales las reglas se aplican durante la búsqueda; en discos de red, WSL y carpetas personalizadas el índice omite lo excluido y se actualiza al aplicar. Cuando una exclusión cubre una regla de prioridad, aparece un aviso de conflictos sobre la lista y la regla cubierta no surte efecto.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Las reglas admiten <strong>adición individual</strong> e <strong>importación/exportación por lotes</strong>: pulsa <strong>Generar desde la Lista</strong> para exportarlas a texto, edítalo y pulsa <strong>Aplicar a la Lista</strong> para actualizarlas en bloque. Si alguna línea del texto por lotes no se reconoce, no se aplica ninguna y el texto queda en el cuadro para que lo corrijas.</p></div>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};